    74  // Dummy memory wrappers for use with zlib
    75  static void *dummy_alloc(void * /*opaque*/, unsigned int items, unsigned int size) {
    76      return ::operator new(items *size);
    77  }
    78
    79  static void dummy_free(void * /*opaque*/, void *address) {
    80      return ::operator delete(address);
