   212  /** Helper structure analogue to aiScene */
   213  struct Scene
   214  {
   215      Node* mRootNode;
   216
   217      std::vector<Mesh*> mGlobalMeshes; // global meshes found outside of any frames
   218      std::vector<Material> mGlobalMaterials; // global materials found outside of any meshes.
   219
   220      std::vector<Animation*> mAnims;
   221      unsigned int mAnimTicksPerSecond;
   222
   223      Scene() AI_NO_EXCEPT
   224      : mRootNode(nullptr)
   225      , mGlobalMeshes()
   226      , mGlobalMaterials()
   227      , mAnimTicksPerSecond(0) {
   228          // empty
   229      }
   230      ~Scene() {
   231          delete mRootNode;
   232          mRootNode = nullptr;
   233          for (unsigned int a = 0; a < mGlobalMeshes.size(); ++a ) {
   234              delete mGlobalMeshes[a];
   235          }
   236          for (unsigned int a = 0; a < mAnims.size(); ++a ) {
   237              delete mAnims[a];
   238          }
   239      }
   240  };
